//			SetCreatedAt(v+v).
//		}).
//		Exec(ctx)
func (_c *OrderPayableCreateBulk) OnConflict(opts ...sql.ConflictOption) *OrderPayableUpsertBulk {
	_c.conflict = opts
	return &OrderPayableUpsertBulk{
		create: _c,
	}
}

// OnConflictColumns calls `OnConflict` and configures the columns
